namespace sv_d5d6de14ceaf45bf842112ff75e0254d.Components.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service holding per-circuit theme state.
/// In Interactive Server mode, "scoped" means per-circuit,
/// so each user gets an independent instance that survives enhanced navigations.
/// </summary>
public class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyStateChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyStateChanged();
        }
    }

    public event Action? OnChange;

    private void NotifyStateChanged() => OnChange?.Invoke();
}

@* 
    Interactive island embedded in the static layout.
    Because it has its own @rendermode, it joins the circuit and
    shares the same scoped ThemeService instance as all other
    interactive components.
*@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<span class="badge rounded-pill" style="background-color: @ThemeService.AccentColor;">
    @ThemeLabel
</span>

@code {
    private string ThemeLabel => ThemeService.Theme switch
    {
        ThemeMode.Light => "☀️ Light",
        ThemeMode.Dark => "🌙 Dark",
        _ => "💻 System"
    };

    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h3>User Preferences</h3>

<div class="mb-3">
    <label class="form-label">Theme</label>
    <select class="form-select" @bind="SelectedTheme">
        <option value="@ThemeMode.Light">Light</option>
        <option value="@ThemeMode.Dark">Dark</option>
        <option value="@ThemeMode.System">System</option>
    </select>
</div>

<div class="mb-3">
    <label class="form-label">Accent Color</label>
    <input type="color" class="form-control form-control-color"
           @bind="AccentColor" @bind:event="oninput" />
</div>

<p>
    Current: <strong>@ThemeService.Theme</strong> /
    <span style="color: @ThemeService.AccentColor;">@ThemeService.AccentColor</span>
</p>

@code {
    private ThemeMode SelectedTheme
    {
        get => ThemeService.Theme;
        set => ThemeService.Theme = value;
    }

    private string AccentColor
    {
        get => ThemeService.AccentColor;
        set => ThemeService.AccentColor = value;
    }

    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

